// might_throw() is a function that could throw an exception.
void might_throw();

// process_data is exception-neutral. It doesn't throw directly,
// but it doesn't prevent exceptions from might_throw() from propagating.
// It should NOT be marked noexcept.
void process_data() {
    // ... some work ...
    might_throw(); // if this throws, process_data lets it pass through
    // ... more work ...
}

// The caller is responsible for handling potential exceptions.
void high_level_operation() {
    try {
        process_data();
    } catch (...) {
        // handle the error that propagated from might_throw()
    }
}
